.header {
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 48px;
  padding: 0 var(--space-lg);
  background-color: rgba(13, 59, 46, 0.85); /* --color-bg at 85% opacity */
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.logo {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.contact {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
}

.phone {
  color: var(--color-text);
  text-decoration: none;
  white-space: nowrap;
}

.phone:hover {
  color: var(--color-accent);
}

.separator {
  color: var(--color-text-muted);
  user-select: none;
}

/* Hide phone numbers on mobile, show on tablet+ */
@media (max-width: 639px) {
  .contact {
    display: none;
  }
}

@media (min-width: 640px) {
  .header {
    padding: 0 var(--space-xl);
  }

  .contact {
    font-size: var(--font-size-sm);
  }
}

