"use client";

import { useState } from "react";
import Image from "next/image";
import { Section } from "./Section";
import { renderMarkdown } from "../utils/markdown";
import styles from "./Services.module.css";

interface ServiceItem {
  id: string;
  title: string;
  image: string;
  summary: string;
  descriptionMarkdown: string;
}

const SERVICE_ITEMS: ServiceItem[] = [
  {
    id: "1",
    title: "Daily prayers and weekly Halaqa",
    image: "/components/services/1/title.png",
    summary:
      "The weekly halaqa complements daily prayers by fostering a collective environment of learning and fellowship that enriches spiritual life and promotes communal unity.",
    descriptionMarkdown:
      "The weekly halaqa complements the essence of daily prayers by fostering a collective spirit of learning, sharing, and fellowship. Rooted in Islamic tradition, the halaqa is a circle of knowledge and wisdom where community members come together under the guidance of a knowledgeable leader or scholar.\n\nThrough Al Slaam, the practice of daily prayers and the vibrant gatherings of the weekly halaqa, Muslims enrich their spiritual lives, embody peace, and foster unity in the service of Allah and humanity.",
  },
  {
    id: "2",
    title: "Qur'an Classes For All Ages",
    image: "/components/services/2/title.png",
    summary:
      "Al Slaam Quran Academy provides personalized, comprehensive Quranic education for all ages, focusing on recitation, memorization, and the practical application of Quranic wisdom in daily life.",
    descriptionMarkdown:
      "Al Slaam Quran Academy takes immense pride in offering comprehensive Quran classes tailored for all ages, with the vision of spreading knowledge and understanding of the Holy Quran among individuals from diverse backgrounds. From young children to seasoned adults, our qualified and compassionate instructors ensure that each student receives personalized attention and guidance on their Quranic journey.\n\nFor teenagers and adults seeking to deepen their understanding of the Quran and its meanings, we offer insightful classes and discussions on the profound messages within the Quranic verses. Our Quran classes for all ages encompass not only the recitation and memorization of the Quran but also the practical application of its principles in daily life.",
  },
  {
    id: "3",
    title: "Islamic Studies",
    image: "/components/services/3/title.png",
    summary:
      "Our mission is to provide transformative Islamic education that empowers learners of all ages to apply faith-driven values like compassion and justice to the challenges of the modern world.",
    descriptionMarkdown:
      "Our mission is to provide transformative Islamic education that empowers learners of all ages to apply faith-driven values like compassion and justice to the challenges of the modern world.",
  },
  {
    id: "4",
    title: "Family Counselling",
    image: "/components/services/4/title.png",
    summary:
      "Our family counseling provides holistic, Islamically-rooted support to resolve conflicts and strengthen the bonds of a thriving community.",
    descriptionMarkdown:
      "Our family counseling provides holistic, Islamically-rooted support to resolve conflicts and strengthen the bonds of a thriving community.",
  },
  {
    id: "5",
    title: "Psychoeducation Sessions",
    image: "/components/services/5/title.png",
    summary:
      "Our psychoeducation sessions provide Islamically-integrated tools and strategies to enhance community mental health, resilience, and emotional well-being.",
    descriptionMarkdown:
      "Our psychoeducation sessions provide Islamically-integrated tools and strategies to enhance community mental health, resilience, and emotional well-being.",
  },
  {
    id: "6",
    title: "Youth Programs",
    image: "/components/services/6/title.png",
    summary:
      "Our youth programs empower young individuals to develop leadership skills and a strong Islamic identity through mentorship and community service.",
    descriptionMarkdown:
      "Our youth programs empower young individuals to develop leadership skills and a strong Islamic identity through mentorship and community service.",
  },
];

function ServiceCard({ item }: { item: ServiceItem }) {
  const [expanded, setExpanded] = useState(false);

  return (
    <div className={styles.card}>
      <div className={styles.imageWrapper}>
        <Image
          src={item.image}
          alt={item.title}
          width={300}
          height={200}
          className={styles.image}
        />
      </div>
      <div className={styles.textContent}>
        <h3 className={styles.cardTitle}>{item.title}</h3>
        <p className={styles.summary}>{item.summary}</p>
        <button
          className={styles.toggle}
          onClick={() => setExpanded(!expanded)}
          aria-expanded={expanded}
        >
          {expanded ? "Show Less ▲" : "Read More ▼"}
        </button>
        {expanded && (
          <div
            className={styles.description}
            dangerouslySetInnerHTML={{
              __html: renderMarkdown(item.descriptionMarkdown),
            }}
          />
        )}
      </div>
    </div>
  );
}

export function Services() {
  return (
    <Section title="Services">
      <div className={styles.grid}>
        {SERVICE_ITEMS.map((item) => (
          <ServiceCard key={item.id} item={item} />
        ))}
      </div>
    </Section>
  );
}

input.content:
/* ── Grid ─────────────────────────────────────────────────────────────── */
.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-xl);
}

/* ── Card ────────────────────────────────────────────────────────────── */
.card {
  display: flex;
  flex-direction: column;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card:hover {
  transform: scale(1.02);
  box-shadow: var(--shadow-card-hover);
}

/* ── Image ───────────────────────────────────────────────────────────── */
.imageWrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 3 / 2;
  overflow: hidden;
}

.image {
  object-fit: cover;
  width: 100%;
  height: 100%;
}

/* ── Text ────────────────────────────────────────────────────────────── */
.textContent {
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  flex: 1;
}

.cardTitle {
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 var(--space-sm);
}

.summary {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin: 0 0 var(--space-md);
}

/* ── Toggle button ───────────────────────────────────────────────────── */
.toggle {
  background: none;
  border: 1px solid var(--color-accent);
  color: var(--color-accent);
  font-size: var(--font-size-xs);
  font-weight: 600;
  cursor: pointer;
  padding: var(--space-xs) var(--space-sm);
  border-radius: var(--radius-full);
  align-self: flex-start;
  margin-top: auto;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.toggle:hover {
  background-color: var(--color-accent);
  color: #0d3b2e;
}

.toggle:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* ── Expanded description ────────────────────────────────────────────── */
.description {
  margin-top: var(--space-md);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  line-height: 1.7;
}

.description p {
  margin: 0 0 var(--space-sm);
}

/* ── Responsive ──────────────────────────────────────────────────────── */

/* Tablet: 2 columns */
@media (min-width: 640px) {
  .grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Desktop: 3 columns */
@media (min-width: 1024px) {
  .grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

